# Compila un .cs de prueba de Unity contra las DLL del editor y del proyecto (sin abrir Unity),
# con el Roslyn que trae el propio editor. Solo comprueba que compila; no toca el proyecto.
#   blender -b --python tests/n_csc.py -- PROYECTO_UNITY
import sys, os, glob, subprocess, base64, tempfile
proj = sys.argv[sys.argv.index("--") + 1:][0]
SRCS = {"Fase9": base64.b64decode("").decode("utf-8"), "Fase7_control": base64.b64decode("").decode("utf-8")}
ver = open(os.path.join(proj, "ProjectSettings", "ProjectVersion.txt")).read().split("m_EditorVersion:")[1].split()[0]
print("Unity", ver)
cands = []
for root in [r"C:\Program Files\Unity\Hub\Editor", r"C:\Program Files\Unity", r"D:\Unity", r"E:\Unity",
             r"D:\Program Files\Unity\Hub\Editor", r"E:\Program Files\Unity\Hub\Editor", r"D:\Unity Hub", r"E:\Unity Hub"]:
    cands += glob.glob(os.path.join(root, ver, "Editor")) + glob.glob(os.path.join(root, "*", ver, "Editor"))
hub = os.path.expandvars(r"%APPDATA%\UnityHub\secondaryInstallPath.json")
if os.path.exists(hub):
    p = open(hub).read().strip().strip('"')
    print("hub:", p)
    if p:
        cands += glob.glob(os.path.join(p, ver, "Editor"))
print("candidatos:", cands)
ed = next((c for c in cands if os.path.isdir(os.path.join(c, "Data", "Managed"))), None)
if not ed:
    print("FAIL no encuentro el editor de Unity", ver); sys.exit(1)
data = os.path.join(ed, "Data")
dotnet = os.path.join(data, "NetCoreRuntime", "dotnet.exe")
csc = os.path.join(data, "DotNetSdkRoslyn", "csc.dll")
print(dotnet, os.path.exists(dotnet)); print(csc, os.path.exists(csc))
refs = glob.glob(os.path.join(data, "Managed", "UnityEngine", "*.dll"))
# the .NET Framework profile the project's assemblies were built against
api = os.path.join(data, "MonoBleedingEdge", "lib", "mono", "4.7.1-api")
refs += glob.glob(os.path.join(api, "*.dll")) + glob.glob(os.path.join(api, "Facades", "*.dll"))
sa = os.path.join(proj, "Library", "ScriptAssemblies")
refs += [p for p in glob.glob(os.path.join(sa, "*.dll"))]
seen, uniq = set(), []
for r in refs:
    b = os.path.basename(r).lower()
    if b in seen: continue
    seen.add(b); uniq.append(r)
print(len(uniq), "referencias")
for tag, SRC in SRCS.items():
    print("=====", tag)
    tmp = tempfile.mkdtemp()
    src = os.path.join(tmp, "Prueba.cs"); open(src, "w", encoding="utf-8").write(SRC)
    rsp = os.path.join(tmp, "a.rsp")
    open(rsp, "w", encoding="utf-8").write("\n".join(["-target:library", "-nologo", "-nostdlib+", "-langversion:9.0",
        "-define:UNITY_EDITOR;UNITY_2022_3_OR_NEWER", "-out:" + os.path.join(tmp, "Prueba.dll")]
        + ['-r:"%s"' % r for r in uniq] + ['"%s"' % src]))
    p = subprocess.run([dotnet, csc, "@" + rsp], capture_output=True, text=True)
    print(p.stdout); print(p.stderr)
    errs = [l for l in p.stdout.splitlines() if ": error " in l]
    warns = [l for l in p.stdout.splitlines() if ": warning " in l]
    print("%d errores, %d avisos" % (len(errs), len(warns)))
    print("RESULTADO %s:" % tag, "COMPILA" if p.returncode == 0 else "NO COMPILA")
